import { Notifications } from '@mantine/notifications';
import type { Meta, StoryObj } from '@storybook/nextjs-vite';
import { within } from 'storybook/test';

import { defaultMoreGamesFormData } from '@/tests/mocks/data/moreGamesForm';
import type { CreateMoreGameDaysProxy } from '@/types/actions/CreateMoreGameDays';

import { MoreGamesForm } from './MoreGamesForm';

const meta = {
    title: 'Forms/MoreGamesForm',
    component: MoreGamesForm,
    decorators: [
        (Story) => (
            <>
                <Notifications />
                <Story />
            </>
        ),
    ],
    parameters: {
        layout: 'fullscreen',
    },
    tags: ['autodocs'],
} satisfies Meta<typeof MoreGamesForm>;

export default meta;
type Story = StoryObj<typeof meta>;

const mockCreateMoreGameDays: CreateMoreGameDaysProxy = async () => Promise.resolve([]);

export const Primary: Story = {
    args: {
        ...defaultMoreGamesFormData,
        onCreateMoreGameDays: mockCreateMoreGameDays,
    },
    play: async function ({ canvasElement, userEvent, viewMode }) {
        if (viewMode === 'docs') return;

        const canvas = within(canvasElement);
        const firstComment = await canvas.findByLabelText(
            `Comment for ${defaultMoreGamesFormData.rows[0].date}`,
        );
        const firstCheckbox = await canvas.findByLabelText(
            `Game scheduled for ${defaultMoreGamesFormData.rows[0].date}`,
        );
        const submitButton = await canvas.findByRole('button', { name: /Create game days/i });

        await userEvent.type(firstComment, 'Bring bibs');
        await userEvent.click(firstCheckbox);
        await userEvent.click(submitButton);

        const body = canvasElement.ownerDocument.body;
        await within(body).findByText('Game days created successfully', {}, { timeout: 6000 });
    },
};

content.text:
Storybook "play" tests are interaction tests embedded directly in `.stories.tsx` files — a `play` function attached to a story that runs after the story renders, simulating real user interaction and asserting on the result. In this repo they're powered by `@storybook/addon-vitest`, which lets `npm run test:storybook` (just `vitest run` under a Storybook-aware config) execute every story's `play` function as an actual test, headlessly, in addition to being viewable/re-runnable in the Storybook UI itself.

How it works here, using [MoreGamesForm.stories.tsx](src/components/MoreGamesForm/MoreGamesForm.stories.tsx:37) as a concrete example:

```tsx
play: async function ({ canvasElement, userEvent, viewMode }) {
    if (viewMode === 'docs') return;   // skip when rendered in the Autodocs tab

    const canvas = within(canvasElement);
    const firstComment = await canvas.findByLabelText(`Comment for ${...}`);
    const submitButton = await canvas.findByRole('button', { name: /Create game days/i });

    await userEvent.type(firstComment, 'Bring bibs');
    await userEvent.click(submitButton);

    const body = canvasElement.ownerDocument.body;
    await within(body).findByText('Game days created successfully', {}, { timeout: 6000 });
},
```

Key points:

- **`canvasElement` + `within`** scope queries to the rendered story's DOM, mirroring Testing Library. `userEvent` (from `storybook/test`) drives realistic typed/clicked interactions.
- **Accessible queries only** — `findByLabelText`, `findByRole`, `findByText` — consistent with this project's rule of avoiding `data-testid`.
- **Assertions on outcomes**, not implementation — here it waits for a Mantine notification ("Game days created successfully") to appear in `document.body`, since notifications portal outside `canvasElement`.
- **`viewMode` guard** — `play` functions also fire when Storybook renders the story inside the Autodocs page; guarding on `viewMode === 'docs'` prevents the interaction from running (and erroring) there.
- **Mocked server actions as props** — `onCreateMoreGameDays: mockCreateMoreGameDays` stands in for the real server action, matching the "server actions injected as props" architecture in this codebase.

Other examples worth looking at for variations: [DeleteAccountForm.stories.tsx](src/components/DeleteAccountForm/DeleteAccountForm.stories.tsx), [PlayerProfileForm.stories.tsx](src/components/PlayerProfileForm/PlayerProfileForm.stories.tsx), [NewPlayerForm.stories.tsx](src/components/NewPlayerForm/NewPlayerForm.stories.tsx), and [EnquiryForm.stories.tsx](src/components/EnquiryForm/EnquiryForm.stories.tsx).

Effectively, play tests give you component-level integration tests that exercise the real rendered UI (Mantine components included) through user-facing interactions, run both visually in Storybook and headlessly via `npm run test:storybook`/CI.
